function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const small = size === 'small';
  const names = ['Winston', 'Jonathan', 'Annabelle', 'Marwan', 'Khaled', 'Ana', 'Ana'];
  const customerCount = small ? pick(6) : 400;
  const Customers = [], Orders = [];
  // Ids are shuffled so that id order and name order disagree.
  const ids = Array.from({ length: customerCount }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = pick(i + 1); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  for (const id of ids) Customers.push([id, small ? names[pick(names.length)] : `${names[pick(5)].slice(0, 5)}${pick(60)}`]);
  const day = k => new Date(Date.UTC(2019, 11, 25) + k * 86400000).toISOString().slice(0, 10);
  const span = small ? 12 : 900, target = customerCount === 0 ? 0 : small ? pick(9) : 2000;
  const used = new Set();
  for (let tries = 0; Orders.length < target && tries < target * 4; tries++) {
    const customer = small && rand() < 0.5 ? Customers[0][0] : Customers[pick(customerCount)][0];
    const date = day(pick(span)), key = `${customer}|${date}`;
    if (used.has(key)) continue;
    used.add(key);
    Orders.push([Orders.length + 1, date, customer, 1 + pick(small ? 200 : 2000)]);
  }
  return [{ Customers, Orders }];
}
